const app = document.querySelector('#app');
const toast = document.querySelector('#toast');
const state = { summary: null, departments: [], pathways: [], learner: null, user: null, mastery: [], currentCourse: null };

const setDeviceProfile = () => {
  const width = window.innerWidth;
  document.documentElement.dataset.device = width < 768 ? 'mobile' : width < 1100 ? 'tablet' : 'desktop';
  document.documentElement.dataset.platform = /Android/i.test(navigator.userAgent) ? 'android' : /iPhone|iPad|iPod/i.test(navigator.userAgent) ? 'ios' : 'web';
};

const escapeHTML = (value) => String(value ?? '').replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[character]));
const api = async (path, options = {}) => {
  const response = await fetch(`/api${path}`, { credentials: 'include', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || 'Something went wrong.');
  return body;
};
const showToast = (message) => { toast.textContent = message; toast.classList.add('show'); window.setTimeout(() => toast.classList.remove('show'), 3600); };
const navigate = (target) => { window.location.hash = target; window.scrollTo({ top: 0, behavior: 'smooth' }); };
const departmentById = (id) => state.departments.find((department) => department.id === id);
const departmentForCourse = (course) => state.departments.find((department) => department.name === course.primaryDepartment);
const courseHref = (course) => { const department = departmentForCourse(course); return department ? `#department/${encodeURIComponent(department.id)}/course/${encodeURIComponent(course.id)}` : '#catalogue'; };
const enrolHref = (course) => { const department = departmentForCourse(course); return department ? `#department/${encodeURIComponent(department.id)}/enrol/${encodeURIComponent(course.id)}` : '#catalogue'; };
const courseBadgeClass = (department) => ({ 'IT and Technology': 'blue', 'Hospitality Management': 'red', 'Tourism and Destination Management': 'green', Interdisciplinary: 'purple' }[department] || '');
const practiceType = (course) => {
  if (!course) return null;
  if (['tec-001', 'gac-001'].includes(course.id)) return 'productivity';
  if (course.id === 'tec-002') return 'web';
  if (['tec-003', 'tec-010', 'tur-003'].includes(course.id)) return 'workflow';
  if (['tec-004', 'bus-003', 'bus-006', 'bus-007', 'bus-008', 'hos-006', 'hos-008'].includes(course.id)) return 'data';
  if (['tec-008', 'tec-009', 'xdp-006'].includes(course.id)) return 'ai';
  if (['tec-005', 'tec-006', 'tec-007'].includes(course.id)) return 'systems';
  return null;
};
const practiceHref = (course, week = 1) => { const department = departmentForCourse(course); return department ? `#department/${encodeURIComponent(department.id)}/practice/${encodeURIComponent(course.id)}/${week}` : '#catalogue'; };
const departmentImage = (department) => ({ business: '/images/business-liberian-youth.jpg', technology: '/images/technology-liberian-youth.jpg', hospitality: '/images/hospitality-liberian-youth.jpg', tourism: '/images/tourism-liberian-youth.jpg', interdisciplinary: '/images/interdisciplinary-liberian-youth.jpg', core: '/images/interdisciplinary-liberian-youth.jpg' }[department.id]);
const route = () => {
  const parts = (window.location.hash.replace(/^#\/?/, '') || 'home').split('/').filter(Boolean).map(decodeURIComponent);
  if (parts[0] === 'department') return { name: 'department', departmentId: parts[1], action: parts[2] || null, id: parts[3] || null, week: parts[4] || '1' };
  return { name: parts[0], id: parts[1] || null };
};
const markDepartmentVisited = (departmentId) => sessionStorage.setItem('gentsacademy_department_context', departmentId);
const hasDepartmentContext = (departmentId) => sessionStorage.getItem('gentsacademy_department_context') === departmentId;

const courseCard = (course) => `<article class="card course-card"><img class="course-image" src="${escapeHTML(course.image)}" alt="${escapeHTML(course.imageAlt)}" loading="lazy"><div class="course-body"><div class="card-topline"><span class="badge ${courseBadgeClass(course.primaryDepartment)}">${escapeHTML(course.primaryDepartment)}</span><span class="course-code">${escapeHTML(course.code)}</span></div><h3>${escapeHTML(course.title)}</h3><p>${escapeHTML(course.description)}</p><div class="meta-row"><span>${escapeHTML(course.level)}</span><span>${course.durationWeeks} weeks</span><span>${course.estimatedHours} hours</span></div><a class="button button-secondary button-small" href="${courseHref(course)}">Open from department</a></div></article>`;

const shell = (content, active = '') => `<header class="navbar"><div class="container navbar-content"><a class="brand" href="#home" aria-label="GentsAcademy home"><span class="logo">GA</span><span class="brand-text">GentsAcademy</span></a><button class="nav-toggle" type="button" aria-label="Toggle navigation" data-action="toggle-nav">Menu</button><nav><ul class="nav-links" data-nav-links><li><a class="nav-link ${active === 'home' ? 'active' : ''}" href="#home">Home</a></li><li><a class="nav-link ${active === 'catalogue' ? 'active' : ''}" href="#catalogue">Departments</a></li><li><a class="nav-link ${active === 'pathways' ? 'active' : ''}" href="#pathways">Pathways</a></li><li><a class="nav-link ${active === 'dashboard' ? 'active' : ''}" href="#dashboard">My learning</a></li><li><a class="nav-link ${active === 'auth' ? 'active' : ''}" href="#auth">${state.user ? 'Account' : 'Sign in'}</a></li><li><a class="button button-primary button-small" href="#catalogue">Choose a department</a></li></ul></nav></div></header>${content}<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="#home"><span class="logo">GA</span><span class="brand-text">GentsAcademy</span></a><p>Education Is The New Freedom. Free, practical, and Liberian-grounded learning for the next generation.</p></div><div><h4>Learn</h4><ul><li><a href="#catalogue">Academic departments</a></li><li><a href="#pathways">Career pathways</a></li><li><a href="#dashboard">My learning</a></li></ul></div><div><h4>Connect</h4><ul><li><a href="#contact">Contact the academy</a></li><li><a href="#about">Our academic model</a></li><li><a href="#certificates">Certificate rules</a></li></ul></div></div><div class="footer-bottom">© ${new Date().getFullYear()} GentsAcademy. Built for learners in Liberia and beyond.</div></div></footer>`;
const loadingView = () => `<main class="section"><div class="container empty-state">Loading GentsAcademy...</div></main>`;
const errorView = (message) => shell(`<main class="section"><div class="container empty-state"><h1>We could not load this view.</h1><p class="error">${escapeHTML(message)}</p><a class="button button-primary" href="#catalogue">Choose a department</a></div></main>`);

const departmentCards = () => state.departments.map((department) => `<article class="card department-card"><img class="department-image" src="${departmentImage(department)}" alt="Young Liberian learners exploring ${escapeHTML(department.name)}" loading="lazy"><div><span class="badge ${department.accent}">${escapeHTML(department.name)}</span><h3>${escapeHTML(department.name)}</h3><p>${escapeHTML(department.summary)}</p></div><a class="card-link" href="#department/${encodeURIComponent(department.id)}">Enter department →</a></article>`).join('');

const homeView = () => { const summary = state.summary || { totalCourses: 41, departments: 6, pathways: 4 }; return shell(`<main><section class="hero"><div class="container hero-grid"><div><span class="eyebrow">Liberian digital skills and service-sector academy</span><h1>Education Is <span class="gradient-text">The New Freedom</span></h1><p class="hero-copy">Learn practical skills, build portfolio evidence, and progress through free certificates in business, technology, hospitality, tourism, and integrated service-sector practice.</p><div class="hero-actions"><a class="button button-primary" href="#catalogue">Choose a department</a><a class="button button-secondary" href="#pathways">View career pathways</a></div></div><aside class="hero-panel"><span class="eyebrow">One school. Clear pathways.</span><h3>Move from learning to evidence.</h3><p>Start in an academic department, then work through structured lessons, university-linked resources, applied assignments, and a realistic capstone.</p><div class="stat-grid"><div class="stat"><strong>${summary.totalCourses}</strong><span>published courses</span></div><div class="stat"><strong>${summary.departments}</strong><span>academic areas</span></div><div class="stat"><strong>${summary.pathways}</strong><span>career pathways</span></div><div class="stat"><strong>Free</strong><span>to enrol and learn</span></div></div></aside></div></section><section class="section section-muted" id="about"><div class="container"><div class="section-heading center"><span class="eyebrow">Department-first learning</span><h2>Choose a capability, then build proof.</h2><p>Courses remain inside their primary academic department. This makes progression, faculty ownership, assessment evidence, and certificate pathways easy to understand.</p></div><div class="grid grid-3"><article class="card"><div class="icon-badge">01</div><h3>Enter a department</h3><p>Choose enterprise, technology, hospitality, tourism, integrated practice, or the shared core before opening a course.</p></article><article class="card"><div class="icon-badge">02</div><h3>Read, watch, apply</h3><p>Every week combines a downloadable GentsAcademy guide with an attributed academic source and a university-led video lesson.</p></article><article class="card"><div class="icon-badge">03</div><h3>Stack evidence</h3><p>Use the shared core and department courses to progress toward an applied career pathway certificate.</p></article></div></div></section><section class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Academic departments</span><h2>Choose the capability you want to own.</h2><p>AI and digital tools are specialisations and cross-department skills, while each course has one clear academic home.</p></div><div class="grid grid-3">${departmentCards()}</div></div></section></main>`, 'home'); };

const catalogueView = () => shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">GentsAcademy catalogue</span><h1>Start inside an academic department.</h1><p>Department-first access keeps every course aligned to its principal learning outcome, assessment evidence, and faculty expertise. Select a department to see its courses.</p></div><div class="grid grid-3">${departmentCards()}</div></div></main>`, 'catalogue');

const departmentView = async (department) => { markDepartmentVisited(department.id); const data = await api(`/departments/${encodeURIComponent(department.id)}/courses`); return shell(`<main><section class="department-hero"><div class="container department-hero-grid"><div><a class="back-link" href="#catalogue">← All departments</a><span class="eyebrow">Academic department</span><h1>${escapeHTML(department.name)}</h1><p>${escapeHTML(department.summary)}</p><p class="notice">You are now inside this department. Its courses, weekly resources, and enrolment journey remain in this academic context.</p></div><img src="${departmentImage(department)}" alt="Young Liberian learners exploring ${escapeHTML(department.name)}"></div></section><section class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Department curriculum</span><h2>${data.total} courses in sequence</h2><p>Choose a course to open its weekly guides, accredited reading, and university-led lesson.</p></div><div class="course-grid">${data.courses.map(courseCard).join('')}</div></div></section></main>`, 'catalogue'); };

const accessGuardView = (department, courseId) => shell(`<main class="section"><div class="container empty-state"><span class="eyebrow">Department access required</span><h1>Enter ${escapeHTML(department.name)} first.</h1><p>This course is academically owned by the ${escapeHTML(department.name)} department. Visit the department to open its curriculum, then choose the course from that department.</p><div class="hero-actions"><a class="button button-primary" href="#department/${encodeURIComponent(department.id)}">Visit ${escapeHTML(department.name)}</a><a class="button button-secondary" href="#catalogue">Browse departments</a></div>${courseId ? `<p class="notice" style="margin-top:1.5rem">Course reference: ${escapeHTML(courseId.toUpperCase())}</p>` : ''}</div></main>`, 'catalogue');

const lessonProgressKey = (course, week) => `gentsacademy.lesson-progress.${course.id}.${week}`;
const lessonIsCompleted = (course, week) => localStorage.getItem(lessonProgressKey(course, week)) === 'complete';
const lessonViewModel = (lesson, course) => { const focus = lesson.focus || 'Complete the weekly learning outcome.'; const reading = lesson.reading || {}; const video = lesson.video || {}; return { ...lesson, selfStudyExplanation: lesson.selfStudyExplanation || `This lesson develops ${focus.toLowerCase()} through a short explanation, an academic reference, and applied evidence.`, essentialQuestion: lesson.essentialQuestion || `How could ${focus.toLowerCase()} improve a real situation connected to ${course.title}?`, learningSteps: lesson.learningSteps?.length ? lesson.learningSteps : [`Read for the main idea: ${focus}`, `Watch for one method or example connected to ${lesson.module || 'this week’s topic'}.`, `Apply the idea locally and save ${course.evidenceType?.toLowerCase() || 'a short piece of evidence'}.`], notes: lesson.notes || { overview: lesson.studyConnection || `This week focuses on ${focus}. Connect the concept to a real Liberian or regional situation, then compare your first idea with the linked academic source.`, explanation: `Move from a situation to a decision and then to evidence. Describe what is happening, identify the people, tools, or constraints involved, and make one small responsible attempt.`, keyIdeas: [`Purpose: connect the week’s work to “${focus}”.`, 'Method: make a small attempt, test it with safe information, and explain the result.', 'Evidence: save a short record another learner could understand and review.'], instructions: [], exercise: lesson.activity || `Complete a practical activity related to ${focus}.`, checks: ['What is the main idea in your own words?', 'Which decision or assumption most affects the result?', 'What evidence would show that your approach is useful and responsible?'] }, reading: { ...reading, kind: reading.kind || 'Academic learning resource', license: reading.license || 'Access terms apply; verify the source page.', officialUrl: reading.officialUrl || reading.url || '#' }, video: { ...video, kind: video.kind || 'University lecture or official educational video', license: video.license || 'Access terms apply; video remains the property of its provider and platform.', officialUrl: video.officialUrl || video.url || '#' } }; };
const assessmentBlock = (lesson, course) => `<details class="assessment-card"><summary>Week ${escapeHTML(lesson.week)} mastery check</summary><form data-form="assessment" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(lesson.week)}" data-correct="${escapeHTML(lesson.focus)}"><p><strong>1. Which statement best matches this week’s focus?</strong></p><label><input type="radio" name="answer" value="${escapeHTML(lesson.focus)}" required> ${escapeHTML(lesson.focus)}</label><label><input type="radio" name="answer" value="unrelated"> A topic unrelated to ${escapeHTML(course.title)}</label><label><input type="radio" name="answer" value="skip"> Skip the evidence and copy a source</label><label for="short-answer-${escapeHTML(course.id)}-${escapeHTML(lesson.week)}">2. Explain the idea in your own words.</label><textarea class="field" id="short-answer-${escapeHTML(course.id)}-${escapeHTML(lesson.week)}" name="shortAnswer" rows="4" minlength="20" required placeholder="Connect the idea to a Liberian or regional example."></textarea><label for="applied-${escapeHTML(course.id)}-${escapeHTML(lesson.week)}">3. Applied evidence</label><textarea class="field" id="applied-${escapeHTML(course.id)}-${escapeHTML(lesson.week)}" name="applied" rows="4" minlength="30" required placeholder="Describe what you would do, make, calculate, or observe."></textarea><p class="form-help">If you used an AI tool, disclose it and rewrite the answer in your own words. The system may surface a visible review warning, but it will not silently accuse or delete your work.</p><button class="button button-primary button-small" type="submit">Submit mastery attempt</button></form></details>`;
const weeklyLessonPanel = (lesson, course, index) => { lesson = lessonViewModel(lesson, course); const completed = lessonIsCompleted(course, lesson.week); return `<article class="lesson-panel ${completed ? 'is-complete' : ''}" data-lesson-panel data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(lesson.week)}"><div class="lesson-panel-topline"><span class="badge blue">Week ${escapeHTML(lesson.week)}</span><span class="course-code">${escapeHTML(lesson.module)}</span><span class="lesson-status" data-lesson-status>${completed ? 'Studied on this device' : `Step ${index + 1} of ${course.durationWeeks}`}</span></div><details class="lesson-panel-main" ${index === 0 ? 'open' : ''}><summary><span><strong>${escapeHTML(lesson.title)}</strong><small>${escapeHTML(lesson.focus)}</small></span><span class="panel-toggle">Open lesson</span></summary><div class="lesson-panel-content"><div class="lesson-intro"><span class="eyebrow">Start here</span><h3>${escapeHTML(lesson.focus)}</h3><p>${escapeHTML(lesson.selfStudyExplanation)}</p><div class="notice"><strong>Essential question:</strong> ${escapeHTML(lesson.essentialQuestion)}</div></div><div class="lesson-panel-grid"><section class="lesson-reading"><span class="eyebrow">Read the idea</span><h4>Original learning note</h4><p>${escapeHTML(lesson.notes.overview)}</p><p>${escapeHTML(lesson.notes.explanation)}</p><h4>Key ideas</h4><ul class="check-list">${lesson.notes.keyIdeas.map((item) => `<li>${escapeHTML(item)}</li>`).join('')}</ul></section><aside class="lesson-steps"><span class="eyebrow">Study sequence</span><h4>Read · watch · apply</h4><ol class="plain-list">${lesson.learningSteps.map((step) => `<li>${escapeHTML(step)}</li>`).join('')}</ol><p class="source-note"><strong>Estimated time:</strong> ${lesson.estimatedHours} hours</p></aside></div><div class="lesson-panel-grid"><section class="lesson-exercise"><span class="eyebrow">Apply it locally</span><h4>Weekly exercise</h4><p>${escapeHTML(lesson.notes.exercise)}</p><p class="notice"><strong>Evidence prompt:</strong> ${escapeHTML(lesson.activity)}</p></section><section class="lesson-checks"><span class="eyebrow">Reflect before submitting</span><h4>Self-check questions</h4><ul class="plain-list">${lesson.notes.checks.map((item) => `<li>${escapeHTML(item)}</li>`).join('')}</ul></section></div><div class="lesson-resource-grid"><section class="lesson-materials"><span class="eyebrow">Academic reading</span><h4>${escapeHTML(lesson.reading.title)}</h4><p><strong>${escapeHTML(lesson.reading.provider)}</strong></p><p class="source-note">${escapeHTML(lesson.reading.kind)} · ${escapeHTML(lesson.reading.license)}</p><a class="card-link" href="${escapeHTML(lesson.reading.officialUrl || lesson.reading.url)}" target="_blank" rel="noopener noreferrer">Open official resource ↗</a></section><section class="lesson-materials"><span class="eyebrow">Optional reference file</span><h4>${escapeHTML(lesson.pdfTitle)}</h4><p>Download the original study guide for offline revision or low-bandwidth study after completing the on-site lesson.</p><a class="button button-secondary button-small" href="${escapeHTML(lesson.pdfPath)}" download>Download PDF</a></section></div><div class="lesson-video"><div><span class="eyebrow">Watch the method</span><h4>${escapeHTML(lesson.video.title)}</h4><p><strong>${escapeHTML(lesson.video.provider)}</strong></p><p class="source-note">${escapeHTML(lesson.video.kind)} · ${escapeHTML(lesson.video.license)}</p><a class="card-link" href="${escapeHTML(lesson.video.officialUrl || lesson.video.url)}" target="_blank" rel="noopener noreferrer">Open official source in a new tab ↗</a>${practiceType(course) ? `<a class="button button-secondary button-small practice-link" href="${practiceHref(course, lesson.week)}">Practise on site ↗</a>` : ''}</div>${lesson.video.embedUrl ? `<iframe loading="lazy" title="${escapeHTML(lesson.video.title)}" src="${escapeHTML(lesson.video.embedUrl)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>` : '<div class="video-fallback"><span class="icon-badge">▶</span><p>This official source opens in a new tab because an embeddable player is not available.</p></div>'}</div><div class="lesson-actions"><button class="button button-quiet button-small" type="button" data-action="mark-lesson" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(lesson.week)}">${completed ? 'Mark as needing review' : 'Mark lesson as studied'}</button><span class="form-help">This local study marker is separate from assessed mastery.</span></div>${assessmentBlock(lesson, course)}</div></details></article>`;
};
const weeklyMaterialsSection = (lessons = [], course = null) => `<section class="detail-section weekly-materials"><div class="section-heading"><span class="eyebrow">Interactive weekly school</span><h2>Study on site first</h2><p>Open each guided panel to read the original note, follow the local study sequence, practise with the academic reference, and submit mastery evidence. The PDF remains available as an optional offline companion.</p></div><div class="lesson-list">${lessons.map((lesson, index) => weeklyLessonPanel(lesson, course, index)).join('')}</div></section>`;
const detailView = (course, department, weeklyLessons) => shell(`<main class="course-detail"><div class="container"><a class="back-link" href="#department/${encodeURIComponent(department.id)}">← Back to ${escapeHTML(department.name)}</a><div class="detail-hero"><div><span class="badge ${courseBadgeClass(course.primaryDepartment)}">${escapeHTML(course.primaryDepartment)}</span><span class="course-code" style="margin-left:.7rem">${escapeHTML(course.code)}</span><h1>${escapeHTML(course.title)}</h1><p>${escapeHTML(course.description)}</p><div class="detail-meta"><div class="detail-stat"><small>Level</small><strong>${escapeHTML(course.level)}</strong></div><div class="detail-stat"><small>Length</small><strong>${course.durationWeeks} weeks</strong></div><div class="detail-stat"><small>Workload</small><strong>${course.estimatedHours} hours</strong></div><div class="detail-stat"><small>Certificate</small><strong>${escapeHTML(course.certificateType)}</strong></div></div><div class="hero-actions"><a class="button button-primary" href="${enrolHref(course)}">Enrol for free</a><a class="button button-secondary" href="#dashboard">Open my learning</a></div></div><img class="detail-hero-image" src="${escapeHTML(course.image)}" alt="${escapeHTML(course.imageAlt)}"></div><div class="detail-layout"><div><section class="detail-section"><h2>What you will learn</h2><ul class="check-list">${course.outcomes.map((outcome) => `<li>${escapeHTML(outcome)}</li>`).join('')}</ul></section><section class="detail-section"><h2>Weekly modules</h2>${course.modules.map((module) => `<details class="module"><summary>Weeks ${escapeHTML(module.week)} · ${escapeHTML(module.title)}</summary><div class="module-content"><p>${escapeHTML(module.activity)}</p><p><strong>Estimated study time:</strong> ${module.estimatedHours} hours for this module.</p></div></details>`).join('')}</section>${weeklyMaterialsSection(weeklyLessons, course)}<section class="detail-section"><h2>Assessment plan</h2><div class="info-box"><div class="assessment-bar"><span></span><span></span><span></span><span></span></div><div class="assessment-legend"><span><b>20%</b> knowledge checks</span><span><b>30%</b> applied assignments</span><span><b>20%</b> practical demonstration</span><span><b>30%</b> capstone</span></div><p>Pass threshold: <strong>70%</strong>. Assessment should prove the capability claimed by the course.</p></div></section></div><aside><div class="info-box"><h3>Department access</h3><p>This course belongs to <strong>${escapeHTML(department.name)}</strong>. Returning learners should always reopen it from this department.</p></div><div class="info-box"><h3>Entry requirements</h3><p>${escapeHTML(course.prerequisites)}. This course is open access and designed for online and mobile-friendly study.</p></div><div class="info-box"><h3>Capstone evidence</h3><p>${escapeHTML(course.capstone)}</p><p><strong>Evidence type:</strong> ${escapeHTML(course.evidenceType)}</p></div><div class="info-box"><h3>Career relevance</h3><ul class="plain-list">${course.careerRoles.map((role) => `<li>${escapeHTML(role)}</li>`).join('')}</ul></div><div class="info-box"><h3>Certificate rules</h3><p>${escapeHTML(course.completionRule)}</p><a href="#certificates">View all credential rules →</a></div></aside></div><section class="detail-section" style="margin-top:2rem"><h2>Related courses</h2><div class="course-grid">${(state.currentCourse?.related || []).map(courseCard).join('')}</div></section></div></main>`, 'catalogue');

const enrolView = (course, department) => shell(`<main class="section"><div class="container"><a class="back-link" href="${courseHref(course)}">← Back to ${escapeHTML(department.name)}</a><div class="section-heading"><span class="eyebrow">Free enrolment · ${escapeHTML(department.name)}</span><h1>Start ${escapeHTML(course.title)}</h1><p>Enrolment now belongs to your verified account so course access and mastery evidence persist safely across devices.</p></div>${state.user ? `<div class="card form-card"><form data-form="enrol"><input type="hidden" name="courseId" value="${escapeHTML(course.id)}"><input type="hidden" name="departmentId" value="${escapeHTML(department.id)}"><label for="learner-name">Your full name</label><input class="field" id="learner-name" name="learnerName" value="${escapeHTML(state.user.displayName)}" required maxlength="100" autocomplete="name"><p class="form-help">Signed in as ${escapeHTML(state.user.email)}.</p><button class="button button-primary" type="submit">Confirm free enrolment</button><p class="notice" style="margin-top:1rem">Do not submit sensitive personal information.</p></form></div>` : `<div class="card form-card"><p>Sign in or create a verified account before enrolling so your assessment attempts and certificate evidence belong to you.</p><a class="button button-primary" href="#auth">Open account access</a></div>`}</div></main>`, 'catalogue');

const practiceLesson = (lessons, week) => lessons.find((lesson) => String(lesson.week) === String(week)) || lessons[0] || { focus: 'Complete the practical activity for this course.', activity: 'Create a small piece of evidence and reflect on what you learned.' };
const practiceDraft = (course, week) => { try { return JSON.parse(localStorage.getItem(`gentsacademy.practice.${course.id}.${week}`) || '{}'); } catch { return {}; } };
const practiceShell = (course, department, week, lesson, body, title) => shell(`<main class="section practice-page"><div class="container"><a class="back-link" href="${courseHref(course)}">← Back to ${escapeHTML(course.title)}</a><div class="section-heading"><span class="eyebrow">Practice lab · ${escapeHTML(department.name)} · Week ${escapeHTML(week)}</span><h1>${escapeHTML(title)}</h1><p>${escapeHTML(lesson.focus || '')} Use this browser workspace to practise, save a draft locally on this device, and then download or copy your evidence into your learner portfolio.</p><div class="notice"><strong>Privacy note:</strong> Your draft stays in this browser’s local storage. Do not enter passwords, private client data, confidential workplace information, or sensitive personal information.</div></div>${body}</div></main>`, 'catalogue');
const practiceView = (course, department, week, lesson) => {
  const type = practiceType(course);
  const draft = practiceDraft(course, week);
  const sharedActions = `<div class="practice-actions"><button type="button" class="button button-primary button-small" data-action="save-practice">Save draft on this device</button><button type="button" class="button button-secondary button-small" data-action="clear-practice">Clear draft</button><span class="practice-status" data-practice-status>Drafts are stored locally.</span></div>`;
  if (type === 'web') return practiceShell(course, department, week, lesson, `<div class="practice-workspace" data-practice="web" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(week)}"><div class="practice-grid practice-grid-3"><div><label for="web-html">HTML structure</label><textarea class="field code-field" id="web-html" data-practice-input="html" rows="16">${escapeHTML(draft.html || '<main class="card">\n  <h1>My local project</h1>\n  <p>Explain the problem this page helps solve.</p>\n</main>')}</textarea></div><div><label for="web-css">CSS style</label><textarea class="field code-field" id="web-css" data-practice-input="css" rows="16">${escapeHTML(draft.css || 'body { font-family: sans-serif; padding: 2rem; }\n.card { border: 2px solid #d6b65c; padding: 1rem; border-radius: 12px; }')}</textarea></div><div><label for="web-js">JavaScript behaviour</label><textarea class="field code-field" id="web-js" data-practice-input="js" rows="16">${escapeHTML(draft.js || 'document.querySelector("h1")?.addEventListener("click", () => alert("Nice interaction!"));')}</textarea></div></div><div class="practice-preview"><div class="card-topline"><h3>Safe preview</h3><button type="button" class="button button-secondary button-small" data-action="run-web-preview">Run preview</button></div><iframe title="Learner HTML preview" data-practice-preview sandbox="allow-scripts"></iframe></div>${sharedActions}</div>`, 'Web development practice studio');
  if (type === 'productivity') return practiceShell(course, department, week, lesson, `<form class="practice-workspace" data-practice="productivity" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(week)}"><div class="practice-grid practice-grid-2"><div class="card"><label for="doc-title">Document title</label><input class="field" id="doc-title" data-practice-input="title" value="${escapeHTML(draft.title || 'Weekly workplace brief')}"><label for="doc-summary">Word-processor style brief</label><textarea class="field" id="doc-summary" data-practice-input="document" rows="12" placeholder="Write a short, well-structured brief with a heading, context, recommendation, and next step.">${escapeHTML(draft.document || '')}</textarea></div><div class="card"><h3>Spreadsheet-style evidence</h3><p>Enter one item per line as <code>item, quantity, unit cost</code>. The lab calculates a total.</p><textarea class="field code-field" data-practice-input="rows" rows="10" placeholder="Notebook, 2, 5\nTransport, 1, 10">${escapeHTML(draft.rows || '')}</textarea><div class="practice-output" data-practice-output>Enter rows to calculate a total.</div></div></div>${sharedActions}</form>`, 'Document and spreadsheet practice studio');
  if (type === 'data') return practiceShell(course, department, week, lesson, `<div class="practice-workspace" data-practice="data" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(week)}"><div class="card"><label for="csv-data">Analysis dataset</label><p>Paste comma-separated values with a header row. Example: <code>service,score\narrival,4\ncheckout,5</code></p><textarea class="field code-field" id="csv-data" data-practice-input="csv" rows="13">${escapeHTML(draft.csv || 'service,score\narrival,4\ncheckout,5\ncleanliness,4')}</textarea><button type="button" class="button button-primary button-small" data-action="run-data-summary">Summarise dataset</button><div class="practice-output" data-practice-output>Run the summary to see row count and numeric averages.</div></div>${sharedActions}</div>`, 'Data analysis practice studio');
  if (type === 'ai') return practiceShell(course, department, week, lesson, `<form class="practice-workspace" data-practice="ai" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(week)}"><div class="practice-grid practice-grid-2"><div class="card"><label for="ai-task">Task and context</label><textarea class="field" id="ai-task" data-practice-input="task" rows="7" placeholder="Describe a useful, low-risk work task.">${escapeHTML(draft.task || '')}</textarea><label for="ai-prompt">Your prompt</label><textarea class="field code-field" id="ai-prompt" data-practice-input="prompt" rows="9" placeholder="Role + context + task + constraints + output format...">${escapeHTML(draft.prompt || '')}</textarea></div><div class="card"><label for="ai-response">Example output to evaluate</label><textarea class="field" id="ai-response" data-practice-input="response" rows="9" placeholder="Paste or write a sample output. Do not include private information.">${escapeHTML(draft.response || '')}</textarea><div class="rubric-list"><label><input type="checkbox" data-practice-input="accurate" ${draft.accurate ? 'checked' : ''}> Accurate or clearly marked as uncertain</label><label><input type="checkbox" data-practice-input="safe" ${draft.safe ? 'checked' : ''}> Safe and free of sensitive data</label><label><input type="checkbox" data-practice-input="useful" ${draft.useful ? 'checked' : ''}> Useful for the intended learner or customer</label></div><div class="practice-output" data-practice-output>Evaluate the response against the three checks.</div></div></div>${sharedActions}</form>`, 'Responsible AI practice studio');
  const workflow = type === 'workflow';
  return practiceShell(course, department, week, lesson, `<form class="practice-workspace" data-practice="${workflow ? 'workflow' : 'systems'}" data-course-id="${escapeHTML(course.id)}" data-week="${escapeHTML(week)}"><div class="card"><h3>${workflow ? 'Map a service or booking workflow' : 'Design a safe technical system'}</h3><p>${workflow ? 'Write five steps from a request to a completed service. Add the role responsible for each step.' : 'Describe the user, interface, data, service, security control, and outcome. Keep the design at a beginner-friendly level.'}</p><textarea class="field" data-practice-input="plan" rows="15" placeholder="1. Start with...\n2. Then...\n3. A responsible person checks...">${escapeHTML(draft.plan || '')}</textarea><div class="practice-output" data-practice-output>Save a clear sequence or architecture note as evidence.</div></div>${sharedActions}</form>`, workflow ? 'Workflow mapping practice studio' : 'Systems design practice studio');
};

const authView = () => shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Verified learner account</span><h1>Own your learning record.</h1><p>Create a verified account or sign in to keep mastery progress, assessment attempts, certificates, and course enrolments connected to you across devices.</p></div><div class="grid grid-2"><form class="card form-card" data-form="signup"><h2>Create account</h2><label for="signup-name">Full name</label><input class="field" id="signup-name" name="displayName" required maxlength="100"><label for="signup-email">Email address</label><input class="field" id="signup-email" name="email" type="email" required maxlength="160"><label for="signup-password">Passphrase</label><input class="field" id="signup-password" name="password" type="password" minlength="12" maxlength="128" required><p class="form-help">Use 12 or more characters. Your password is hashed on the server and never stored as plain text.</p><button class="button button-primary" type="submit">Create verified account</button></form><form class="card form-card" data-form="login"><h2>Sign in</h2><label for="login-email">Email address</label><input class="field" id="login-email" name="email" type="email" required maxlength="160"><label for="login-password">Passphrase</label><input class="field" id="login-password" name="password" type="password" required><button class="button button-primary" type="submit">Sign in securely</button><p class="form-help">You must verify your email before signing in for the first time.</p></form></div></div></main>`, 'auth');
const dashboardView = () => state.user ? shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Verified learner dashboard</span><h1>Keep your learning moving.</h1><p>Welcome back, ${escapeHTML(state.user.displayName)}. Your progress is based on demonstrated mastery, not only time spent.</p></div><div class="card dashboard-profile"><div><span class="eyebrow">Verified profile</span><h2>${escapeHTML(state.user.displayName)}</h2><p>${escapeHTML(state.user.email)}</p></div><button class="button button-secondary button-small" data-action="logout">Log out</button></div><div id="dashboard-results"><div class="empty-state"><p>Loading your courses and mastery states...</p></div></div></div></main>`, 'dashboard') : shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Learner dashboard</span><h1>Sign in to keep your learning moving.</h1><p>Your verified account connects enrolments, mastery-gated weekly progress, assessment attempts, certificates, and continue-learning shortcuts across devices.</p></div><div class="card form-card"><p>Already have an account? Sign in. New learners can create a verified account first.</p><a class="button button-primary" href="#auth">Open account access</a></div></div></main>`, 'dashboard');
const renderDashboard = (data) => { const target = document.querySelector('#dashboard-results'); if (!target) return; state.learner = data; if (!data.enrollments.length) { target.innerHTML = '<div class="empty-state"><h3>No enrolments found yet.</h3><p>Choose a department, then enrol in a course to create your learning record.</p><a class="button button-secondary" href="#catalogue">Choose a department</a></div>'; return; } target.innerHTML = `<div class="dashboard-grid"><div class="card"><span class="eyebrow">Learner</span><h2>${escapeHTML(data.email)}</h2><p>${data.enrollments.length} active enrolment${data.enrollments.length === 1 ? '' : 's'}.</p><a class="button button-secondary button-small" href="#catalogue">Add another course</a></div><div class="grid">${data.enrollments.map((enrolment) => { const progress = data.progress.find((item) => item.courseId === enrolment.courseId); const completed = progress?.completedModules || 0; const total = enrolment.course.modules.length; const percent = Math.round((completed / total) * 100); return `<article class="card"><div class="card-topline"><span class="badge ${courseBadgeClass(enrolment.course.primaryDepartment)}">${escapeHTML(enrolment.course.primaryDepartment)}</span><span class="course-code">${escapeHTML(enrolment.course.code)}</span></div><h3>${escapeHTML(enrolment.course.title)}</h3><p>${escapeHTML(enrolment.course.description)}</p><div class="progress-track"><div class="progress-fill" style="width:${percent}%"></div></div><p><strong>${percent}% complete</strong> · ${completed} of ${total} modules</p><a class="button button-secondary button-small" href="${courseHref(enrolment.course)}">Open from department</a><button class="button button-primary button-small" data-action="advance-progress" data-course-id="${escapeHTML(enrolment.course.id)}" data-total="${total}">${completed === total ? 'View certificate rules' : 'Mark next module complete'}</button></article>`; }).join('')}</div></div>`; };

const pathwaysView = () => shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Career pathways</span><h1>Build a stack, not a random list.</h1><p>Each pathway combines the shared core, department skills, cross-department practice, and a portfolio outcome. Course links preserve their own department-access controls.</p></div><div class="grid grid-4">${state.pathways.map((pathway) => `<article class="card pathway-card"><span class="badge purple">Pathway</span><h3>${escapeHTML(pathway.title)}</h3><p>${escapeHTML(pathway.description)}</p><p><strong>${pathway.courseIds.length} recommended courses</strong></p><a class="button button-secondary button-small" href="#pathway/${encodeURIComponent(pathway.id)}">View pathway</a></article>`).join('')}</div></div></main>`, 'pathways');
const pathwayView = (pathway) => shell(`<main class="section"><div class="container"><a class="back-link" href="#pathways">← Back to pathways</a><div class="section-heading"><span class="eyebrow">Professional pathway</span><h1>${escapeHTML(pathway.title)}</h1><p>${escapeHTML(pathway.description)}</p></div><div class="course-grid">${pathway.courses.map(courseCard).join('')}</div><div class="notice" style="margin-top:1.5rem">Select a course only after entering its owning department. Pathway completion requires six to eight courses, a portfolio, and a final integrated project.</div></div></main>`, 'pathways');
const contactView = () => shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Connect with the academy</span><h1>Ask a learning question.</h1><p>Contact the team about pathways, learner support, accessibility, or curriculum partnerships.</p></div><div class="card form-card"><form data-form="contact"><label for="contact-name">Your name</label><input class="field" id="contact-name" name="name" required maxlength="100"><label for="contact-email">Email address</label><input class="field" id="contact-email" name="email" type="email" required maxlength="160"><label for="contact-message">Message</label><textarea class="field" id="contact-message" name="message" rows="6" required maxlength="1000"></textarea><button class="button button-primary" type="submit">Send message</button></form></div></div></main>`);
const certificatesView = () => shell(`<main class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Credentials</span><h1>Clear rules for credible certificates.</h1><p>GentsAcademy certificates describe what was completed, how it was assessed, and how a learner’s evidence can be verified.</p></div><div class="grid grid-3"><article class="card"><span class="badge">Course certificate</span><h3>One course</h3><p>Complete at least 80% of activities, achieve at least 70% on assessments, and submit final evidence.</p></article><article class="card"><span class="badge blue">Department certificate</span><h3>One academic area</h3><p>Complete the shared core, three department courses, and a supervised or assessed capstone.</p></article><article class="card"><span class="badge green">Professional pathway</span><h3>Job-oriented sequence</h3><p>Complete six to eight courses across a defined pathway with a portfolio and final integrated project.</p></article></div></div></main>`);

async function loadAuthenticatedDashboard() { try { const response = await api('/learners/me'); state.learner = response; state.mastery = (await api('/assessments/mastery')).mastery || []; renderAuthenticatedDashboard(response); } catch (error) { showToast(error.message); } }
async function loadState() { if (!state.summary) state.summary = await api('/catalogue-summary'); if (!state.departments.length) state.departments = (await api('/departments')).departments; if (!state.pathways.length) state.pathways = (await api('/pathways')).pathways; if (state.user === null) { try { state.user = (await api('/auth/me')).user; } catch { state.user = null; } } }
const renderAuthenticatedDashboard = (data) => { const target = document.querySelector('#dashboard-results'); if (!target) return; const enrollments = data.enrollments || []; if (!enrollments.length) { target.innerHTML = '<div class="empty-state"><h3>No enrolments found yet.</h3><p>Choose a department and enrol in a course to create your learning record.</p><a class="button button-secondary" href="#catalogue">Choose a department</a></div>'; return; } target.innerHTML = `<div class="grid grid-2">${enrollments.map((item) => { const states = state.mastery.filter((row) => row.courseId === item.course.id); const mastered = states.filter((row) => row.status === 'mastered').length; const total = item.course.durationWeeks; const percent = Math.round((mastered / total) * 100); const next = states.find((row) => row.status !== 'mastered')?.week || 1; return `<article class="card"><div class="card-topline"><span class="badge ${courseBadgeClass(item.course.primaryDepartment)}">${escapeHTML(item.course.primaryDepartment)}</span><span class="course-code">${escapeHTML(item.course.code)}</span></div><h3>${escapeHTML(item.course.title)}</h3><p>${escapeHTML(item.course.description)}</p><div class="progress-track"><div class="progress-fill" style="width:${percent}%"></div></div><p><strong>${percent}% mastery</strong> · ${mastered} of ${total} weeks demonstrated</p><p class="source-note">${percent === 100 ? 'Certificate evidence in progress.' : `Continue with Week ${next}.`}</p><a class="button button-primary button-small" href="${courseHref(item.course)}">Continue learning</a></article>`; }).join('')}</div>`; };
async function render() {
  app.innerHTML = loadingView();
  try {
    await loadState();
    const current = route();
    if (current.name === 'department' && current.departmentId) {
      const department = departmentById(current.departmentId);
      if (!department) throw new Error('Department not found.');
      if (!current.action) { app.innerHTML = await departmentView(department); return; }
      if (!['course', 'enrol', 'practice'].includes(current.action) || !current.id) throw new Error('Learning route not found.');
      if (!hasDepartmentContext(department.id)) { app.innerHTML = accessGuardView(department, current.id); return; }
      const data = await api(`/courses/${encodeURIComponent(current.id)}?departmentId=${encodeURIComponent(department.id)}`);
      state.currentCourse = data;
      if (current.action === 'practice' && !practiceType(data.course)) throw new Error('This course does not have an on-site practice lab yet.');
      app.innerHTML = current.action === 'course' ? detailView(data.course, department, data.weeklyLessons) : current.action === 'practice' ? practiceView(data.course, department, current.week, practiceLesson(data.weeklyLessons, current.week)) : enrolView(data.course, department);
      return;
    }
    if (current.name === 'course' || current.name === 'enrol') { app.innerHTML = shell(`<main class="section"><div class="container empty-state"><span class="eyebrow">Department access required</span><h1>Choose a department first.</h1><p>Courses are opened only from the academic department that owns their learning outcomes and assessment evidence.</p><a class="button button-primary" href="#catalogue">Choose a department</a></div></main>`, 'catalogue'); return; }
    if (current.name === 'catalogue') { app.innerHTML = catalogueView(); return; }
    if (current.name === 'pathways') { app.innerHTML = pathwaysView(); return; }
    if (current.name === 'pathway' && current.id) { const pathway = state.pathways.find((item) => item.id === current.id); if (!pathway) throw new Error('Pathway not found.'); app.innerHTML = pathwayView(pathway); return; }
    if (current.name === 'auth') { app.innerHTML = authView(); return; }
    if (current.name === 'dashboard') { app.innerHTML = dashboardView(); if (state.user) loadAuthenticatedDashboard(); return; }
    if (current.name === 'contact') { app.innerHTML = contactView(); return; }
    if (current.name === 'certificates') { app.innerHTML = certificatesView(); return; }
    app.innerHTML = homeView();
  } catch (error) { app.innerHTML = errorView(error.message); }
}

const getPracticeWorkspace = (element) => element.closest('[data-practice]');
const readPracticeInputs = (workspace) => Object.fromEntries([...workspace.querySelectorAll('[data-practice-input]')].map((input) => [input.dataset.practiceInput, input.type === 'checkbox' ? input.checked : input.value]));
const showPracticeStatus = (workspace, message) => { const target = workspace.querySelector('[data-practice-status]'); if (target) target.textContent = message; };
const updatePracticeOutput = (workspace) => {
  const output = workspace.querySelector('[data-practice-output]');
  if (!output) return;
  const values = readPracticeInputs(workspace);
  if (workspace.dataset.practice === 'productivity') {
    const rows = String(values.rows || '').split(/\n/).map((line) => line.split(',').map((value) => value.trim())).filter((row) => row.length >= 3 && row[0]);
    const total = rows.reduce((sum, row) => sum + (Number(row[1]) || 0) * (Number(row[2]) || 0), 0);
    output.textContent = rows.length ? `${rows.length} line item(s) · estimated total: ${total.toFixed(2)} · Check the currency and assumptions before using this evidence.` : 'Enter rows to calculate a total.';
  } else if (workspace.dataset.practice === 'data') {
    const lines = String(values.csv || '').split(/\n/).map((line) => line.split(',').map((value) => value.trim())).filter((row) => row.some(Boolean));
    const headers = lines.shift() || [];
    const numeric = headers.map((header, index) => ({ header, values: lines.map((row) => Number(row[index])).filter(Number.isFinite) })).filter((column) => column.values.length);
    output.textContent = lines.length ? `${lines.length} data row(s) · ${numeric.map((column) => `${column.header} average ${ (column.values.reduce((sum, value) => sum + value, 0) / column.values.length).toFixed(2) }`).join(' · ') || 'No numeric columns found.'}` : 'Run the summary to see row count and numeric averages.';
  } else if (workspace.dataset.practice === 'ai') {
    const checks = [values.accurate, values.safe, values.useful].filter(Boolean).length;
    output.textContent = `Responsible review score: ${checks}/3 checks selected. Improve any unchecked area before relying on the output.`;
  } else if (workspace.dataset.practice === 'workflow' || workspace.dataset.practice === 'systems') {
    const steps = String(values.plan || '').split(/\n/).map((line) => line.trim()).filter(Boolean);
    output.textContent = steps.length >= 3 ? `${steps.length} planning line(s) captured. Add roles, risks, and a measurable outcome before saving.` : 'Add at least three clear lines so your plan can be reviewed.';
  }
};
const savePracticeWorkspace = (workspace) => {
  const values = readPracticeInputs(workspace);
  localStorage.setItem(`gentsacademy.practice.${workspace.dataset.courseId}.${workspace.dataset.week}`, JSON.stringify(values));
  updatePracticeOutput(workspace);
  showPracticeStatus(workspace, 'Saved privately on this device.');
};
const runWebPreview = (workspace) => {
  const values = readPracticeInputs(workspace);
  const frame = workspace.querySelector('[data-practice-preview]');
  if (!frame) return;
  frame.srcdoc = `<!doctype html><html><head><meta charset="utf-8"><style>${values.css || ''}</style></head><body>${values.html || ''}<script>${values.js || ''}<\/script></body></html>`;
  showPracticeStatus(workspace, 'Preview refreshed in an isolated frame.');
};

document.addEventListener('click', async (event) => { const actionElement = event.target.closest('[data-action]'); if (!actionElement) return; const action = actionElement.dataset.action; if (action === 'toggle-nav') document.querySelector('[data-nav-links]')?.classList.toggle('open'); if (action === 'mark-lesson') { const key = `gentsacademy.lesson-progress.${actionElement.dataset.courseId}.${actionElement.dataset.week}`; const panel = actionElement.closest('[data-lesson-panel]'); const complete = localStorage.getItem(key) === 'complete'; if (complete) { localStorage.removeItem(key); panel?.classList.remove('is-complete'); actionElement.textContent = 'Mark lesson as studied'; panel?.querySelector('[data-lesson-status]')?.replaceChildren(document.createTextNode('Needs review on this device')); showToast('Lesson marked for review.'); } else { localStorage.setItem(key, 'complete'); panel?.classList.add('is-complete'); actionElement.textContent = 'Mark as needing review'; panel?.querySelector('[data-lesson-status]')?.replaceChildren(document.createTextNode('Studied on this device')); showToast('Lesson study marker saved privately on this device.'); } } if (action === 'logout') { try { await api('/auth/logout', { method: 'POST' }); state.user = null; state.learner = null; state.mastery = []; showToast('You are signed out.'); navigate('home'); } catch (error) { showToast(error.message); } } if (action === 'run-web-preview') { const workspace = getPracticeWorkspace(actionElement); if (workspace) runWebPreview(workspace); } if (action === 'run-data-summary') { const workspace = getPracticeWorkspace(actionElement); if (workspace) updatePracticeOutput(workspace); } if (action === 'save-practice') { const workspace = getPracticeWorkspace(actionElement); if (workspace) savePracticeWorkspace(workspace); } if (action === 'clear-practice') { const workspace = getPracticeWorkspace(actionElement); if (workspace) { localStorage.removeItem(`gentsacademy.practice.${workspace.dataset.courseId}.${workspace.dataset.week}`); workspace.querySelectorAll('[data-practice-input]').forEach((input) => { if (input.type === 'checkbox') input.checked = false; else input.value = ''; }); updatePracticeOutput(workspace); showPracticeStatus(workspace, 'Draft cleared from this device.'); } } });
document.addEventListener('input', (event) => { const workspace = event.target.closest('[data-practice]'); if (workspace) updatePracticeOutput(workspace); });
document.addEventListener('submit', async (event) => { const form = event.target; if (!form.matches('[data-form]')) return; event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); try { if (form.dataset.form === 'signup') { const response = await api('/auth/signup', { method: 'POST', body: JSON.stringify(data) }); showToast(response.verificationUrl ? `${response.message} Local verification link: ${response.verificationUrl}` : response.message); form.reset(); return; } if (form.dataset.form === 'login') { const response = await api('/auth/login', { method: 'POST', body: JSON.stringify(data) }); state.user = response.user; showToast(`Welcome, ${response.user.displayName}.`); navigate('dashboard'); return; } if (form.dataset.form === 'enrol') { if (!state.user) { showToast('Sign in before enrolling.'); navigate('auth'); return; } const response = await api('/enrollments', { method: 'POST', body: JSON.stringify(data) }); showToast(response.message); navigate('dashboard'); return; } if (form.dataset.form === 'assessment') { if (!state.user) { showToast('Sign in before submitting mastery evidence.'); navigate('auth'); return; } const correct = data.answer === form.dataset.correct; const shortAnswer = String(data.shortAnswer || ''); const applied = String(data.applied || ''); const aiWarning = /as an ai|language model|chatgpt|generated by ai/i.test(`${shortAnswer} ${applied}`); const score = (correct ? 60 : 0) + (shortAnswer.length >= 30 ? 20 : 0) + (applied.length >= 40 ? 20 : 0); const response = await api('/assessments/attempts', { method: 'POST', body: JSON.stringify({ courseId: form.dataset.courseId, week: Number(form.dataset.week), answers: data, score, aiWarning, feedback: { concepts: [form.dataset.correct], clarification: correct ? null : `Review the week’s central idea: ${form.dataset.correct}. Then try the short explanation and applied evidence again.` } }) }); const panel = form.closest('[data-lesson-panel]'); let feedback = panel?.querySelector('[data-assessment-feedback]'); if (!feedback && panel) { feedback = document.createElement('div'); feedback.dataset.assessmentFeedback = 'true'; feedback.className = 'assessment-feedback'; form.after(feedback); } if (feedback) { feedback.classList.toggle('is-success', Boolean(response.mastery)); feedback.innerHTML = `<strong>${response.mastery ? 'Mastery demonstrated.' : 'Clarification recommended.'}</strong><p>${escapeHTML(response.mastery ? 'The next week is now unlocked. Keep your evidence with your learner portfolio.' : response.clarification || 'Review the highlighted idea and try the assessment again.')}</p>${response.attempt?.aiWarning ? '<p class="form-help">Review note: please disclose any AI assistance and rewrite the evidence in your own words.</p>' : ''}`; } showToast(response.mastery ? 'Mastery demonstrated. The next week is unlocked.' : response.clarification || 'Review the clarification and try again.'); return; } if (form.dataset.form === 'dashboard') { showToast('Dashboard lookup has moved to verified accounts.'); navigate('auth'); return; } if (form.dataset.form === 'contact') { const response = await api('/contact', { method: 'POST', body: JSON.stringify(data) }); form.reset(); showToast(response.message); } } catch (error) { showToast(error.message); } });
window.addEventListener('hashchange', render);
